import {FIELD_LABELS} from './canonical.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const formatValue=v=>Array.isArray(v)?v.map(x=>typeof x==='object'?`${x.label}：${x.question}（依据：${x.basis}）`:x).join('、'):v;
const num=v=>Number(v).toLocaleString('zh-CN');
export const STATUS_LABELS={source_asserted:'来源转录 · 待核',needs_review:'有记录 · 待核',missing:'信息缺失',unconfirmed:'尚未确认',research_interpreted:'已有研究解释 · 待核',research_supported:'已有研究资料 · 待核',research_asserted:'已有研究资料 · 待核',rule_candidate:'规则候选 · 待核',rule_candidate_unverified:'规则候选 · 待核',knowledge_added_unverified:'已有知识补充 · 待核',cross_source_correspondence:'部分书目跨来源一致',external_candidate_unverified:'外部书目候选 · 待核',conflict_needs_review:'存在差异 · 待核'};
STATUS_LABELS.research_interpretation='已有研究解释 · 待核';STATUS_LABELS.research_documented='已有研究资料 · 待核';STATUS_LABELS.analysis_candidate='规则候选 · 待核';
export const statusLabel=s=>STATUS_LABELS[s]||'已有记录 · 待核';
const READING_STAGES={analysis_present:'已有分析，继续核对',content_reading_next:'内容资料待研读',identity_then_content:'先确认资料对应对象',source_search_next:'继续寻找内容资料'};
function readingTask(w){
 const t=w.issue_research_task;if(!t)return '';
 return `<section class="detail-section"><h3>这部作品的下一步</h3><p><strong>${esc(t.label)}</strong> · ${esc(t.reason)}</p><p>${esc(t.next_action)}</p>${w.reading_materials?.length?`<details><summary>已查到的内容资料及对应状态（${num(w.reading_materials.length)}）</summary>${w.reading_materials.map(m=>`<p><a href="${esc(m.source_url)}" target="_blank" rel="noopener noreferrer">${esc(m.id)} ↗</a> · ${m.acquisition_status==='returned'?(m.has_description?'已取得书目简介，仍需研读':'本次记录没有简介'):'此次月度数据未返回此标识'}${m.title?`<br>${esc(m.title)}`:''}${m.acquisition_status==='returned'?`<br>此次资料与先前书目：题名${m.same_dump_title?'相同':'待核'}；至少一位作者${m.same_dump_authors?'相同':'待核'}。文本粒度仍需确认。`:''}</p>`).join('')}</details>`:''}</section>`;
}
export function completionDetail(w){
 const c=w.completion;if(!c)return '<p>补全状态待载入。</p>';
 return `${readingTask(w)}<div class="detail-section audit-detail"><h3>补全与核对状态</h3><p><strong>待独立核对</strong> · 已完成逐字段缺口检查。${c.has_library_correspondence?'题名与作者有跨来源对应；仅确认部分书目字段。':''}</p><p>尚缺或未确认：${c.missing_fields.map(k=>esc(FIELD_LABELS[k])).join('、')||'核心字段已有记录；仍需核对内容'}</p><div class="table-scroll"><table class="audit-field-table"><thead><tr><th>字段</th><th>当前证据状态</th></tr></thead><tbody>${Object.entries(FIELD_LABELS).map(([k,label])=>`<tr><th scope="row">${esc(label)}</th><td class="audit-${esc(c.field_statuses[k])}">${esc(statusLabel(c.field_statuses[k]))}</td></tr>`).join('')}</tbody></table></div>${w.knowledge?`<details><summary>已有知识补充及逐字段依据</summary><p>以下内容来自已有知识，尚未独立逐字段核对；原始研究与来源数据保留。</p><dl>${Object.entries(w.knowledge.fields).map(([k,v])=>`<dt>${esc(({spatial_primary:'主要空间',spatial_secondary:'相关空间',spatial_rationale:'空间依据',duration:'主体叙事跨度',story_era:'故事时代',reach:'最大时间视野',topics:'底层议题',branches:'分支',science_class:'科学前提',science_note:'科学前提依据',issue:'核心问题',issue_facets:'细分议题、问题与情节依据',original_language:'原语',title_original:'原题',title_zh:'中文题名',author:'作者'})[k]||k)}</dt><dd>${esc(formatValue(v))}${w.knowledge.field_notes?.[k]?`<small>${esc(w.knowledge.field_notes[k])}</small>`:''}</dd>`).join('')}</dl><details><summary>逐批原始知识记录及来源</summary><pre>${esc(JSON.stringify(w.knowledge.assertions||[],null,2))}</pre></details></details>`:''}${w.library_checks.length?`<h4>外部书目对照</h4>${w.library_checks.map(r=>`<p><a href="${esc(r.source_url)}" target="_blank" rel="noopener noreferrer">Open Library · ${esc(r.id)} ↗</a><br>${esc(r.title||'未返回')} · ${esc(r.authors.join(' / '))}<br>来源年份：${esc(r.year_comparison.source??'缺失')}；外部年份：${esc(r.year_comparison.library??'缺失')} · ${r.status!=='title_author_correspondence'?'身份或粒度待核，年份暂不作为本作品对照':r.year_comparison.status==='different'?'日期差异，待区分初刊与版本':'题名与至少一位作者对应'}</p>`).join('')}`:''}${c.research_source_comparisons.length?`<details><summary>研究与来源的日期对照</summary><pre>${esc(JSON.stringify(c.research_source_comparisons,null,2))}</pre></details>`:''}<p class="audit-scope">缺失不代表作品没有这一属性。结构检查、跨库书目对应、已有知识和逐字段独立核验分别记录。</p><div id="library-detail"></div></div>`;
}
export function renderCompletion(container,works,metadata){
 const count=key=>works.filter(w=>w.completion?.[key]).length;
 const queueCards=Object.entries(READING_STAGES).map(([stage,label])=>`<article><span>${esc(label)}</span><strong>${num(works.filter(w=>w.issue_research_task?.stage===stage).length)}</strong><p>${stage==='analysis_present'?'具体分析已整理，独立核对继续':stage==='content_reading_next'?'已有简介，对应题名及至少一位作者相同':stage==='identity_then_content'?'有简介，需先区分系列、版本与同名': '继续找作者、出版社、原作等内容资料'}</p></article>`).join('');
 const cards=[['全量条目',works.length,'每条都登记缺口与证据',''],['已有知识补充',works.filter(w=>w.knowledge).length,'可直接查阅，待独立核对','knowledge'],['部分书目对应',count('has_library_correspondence'),'题名与至少一位作者对应','crosschecked'],['日期或版本差异',count('has_conflict'),'保留双方值，继续核对','conflict']];
 container.innerHTML=`<div class="section-heading"><div><span class="eyebrow">RESEARCH / COMPLETION</span><h2>补全进度与证据地图</h2></div><p>每个条目都保留；逐个字段补全，逐项记录证据。</p></div><p class="section-intro">这是截至 ${esc(metadata.date)} 的全量底库状态。已有知识先补入并标注待核；外部主题词只生成分类候选。尚未建立整条作品的完整独立核验，${num(works.length)} 条都能进入后续核对流程。</p><div class="audit-metrics">${cards.map(([title,n,note,value])=>`<article><span>${esc(title)}</span><strong>${num(n)}</strong><p>${esc(note)}</p>${value?`<button data-filter="audit" data-value="${value}">浏览这些条目 →</button>`:''}</article>`).join('')}</div><div class="audit-method"><h3>每条记录的议题研究队列</h3><p>以下状态覆盖当前筛选的全部条目。资料取得仅表示找到了简介，尚未等同于研读、分析或核实。身份和文本粒度有疑点的条目先保留核查步骤。</p><div class="audit-metrics">${queueCards}</div><a href="./assets/issue-research-queue.json.gz" download>下载全量逐条研究队列 ↓</a></div><div class="audit-progress"><h3>从缺口开始浏览</h3><p>“待补全”含缺失及未确认字段；已有候选仍需要研究。点击一行可在作品库中查看所有对应条目。</p>${Object.entries(FIELD_LABELS).filter(([key])=>!['relationships','external_identifiers'].includes(key)).map(([key,title])=>{const missing=works.filter(w=>w.completion?.missing_fields.includes(key)).length;const candidate=works.filter(w=>['rule_candidate','rule_candidate_unverified','analysis_candidate'].includes(w.completion?.field_statuses[key])).length;const knowledge=works.filter(w=>w.completion?.field_statuses[key]==='knowledge_added_unverified').length;const p=((works.length-missing)/works.length*100).toFixed(1);return `<div class="audit-progress-row"><button data-filter="missing" data-value="${key}">${esc(title)} →</button><div class="audit-bar" role="img" aria-label="${esc(title)}：${num(works.length-missing)} 条已有记录，${num(missing)} 条待补全"><span style="width:${p}%"></span></div><span>${num(missing)} 待补全${candidate?` · ${num(candidate)} 候选`:''}${knowledge?` · ${num(knowledge)} 知识补充`:''}</span></div>`;}).join('')}</div><div class="audit-method"><h3>状态如何推进</h3><p>来源转录 → 缺口检查 → 已有知识／分类候选 → 外部书目对应 → 逐字段独立核对。每一步保留依据，原始值和冲突记录可追溯；没有把“已有数据”算成“全部核实”。</p><p>本轮定向核对 ${num(metadata.library.source_records_with_ids)} 条已有 Open Library 作品标识的书目，保留未返回、身份不一致、系列及版本粒度问题。译本语言不作为原语，发表年份不作为故事年份。</p><a href="./assets/record-audit.json.gz" download>下载全量基线字段审计 ↓</a> · <a href="./assets/completion-overlay.json.gz" download>下载补充与核对记录 ↓</a> · <a href="https://github.com/changkun/scifi-exploration/blob/main/docs/audit-methodology.md" target="_blank" rel="noopener noreferrer">核对方法 ↗</a></div>`;
}
